defineFlora('round_tree', {
  name: 'Лиственное дерево',
  footprint: 2, minHeight: 5, choppable: true,
  grow(ctx, x, z, h, opt) {
    const { rand, inb } = ctx;
    const trunk = ctx.block(opt.trunk || 'bark'), crown = ctx.block(opt.crown || 'leaves');
    const th = rand() < 0.35 ? 4 : 3;
    for (let y = h; y < h + th; y++) ctx.set(x, y, z, trunk);
    ctx.soilUnder(x, z);
    const cy = h + th;
    const leaf = (X, Y, Z) => { if (inb(X, Z) && Y < H && ctx.get(X, Y, Z) === 0) ctx.set(X, Y, Z, crown); };
    for (let b = -2; b <= 2; b++) for (let a = -2; a <= 2; a++) {
      const corner = Math.abs(a) === 2 && Math.abs(b) === 2;
      if (!corner) { leaf(x + a, cy - 1, z + b); leaf(x + a, cy, z + b); } else if (rand() < 0.3) leaf(x + a, cy, z + b);
    }
    for (let b = -1; b <= 1; b++) for (let a = -1; a <= 1; a++) if (Math.abs(a) + Math.abs(b) < 2 || rand() < 0.5) leaf(x + a, cy + 1, z + b);
    return { th, crownY: cy - 1 };
  },
})

defineFlora('pine', {
  name: 'Ель',
  footprint: 1, minHeight: 5, choppable: true,
  grow(ctx, x, z, h, opt) {
    const { rand, inb } = ctx;
    const trunk = ctx.block(opt.trunk || 'bark'), crown = ctx.block(opt.crown || 'pine_needles');
    const th = rand() < 0.5 ? 2 : 3;
    const tiers = rand() < 0.45 ? [2, 1, 2, 1, 1, 0, 0] : [2, 1, 1, 0, 0];    // radius per level above the trunk
    for (let y = h; y < h + th + tiers.length - 2; y++) ctx.set(x, y, z, trunk);
    ctx.soilUnder(x, z);
    const leaf = (X, Y, Z) => { if (inb(X, Z) && Y < H && ctx.get(X, Y, Z) === 0) ctx.set(X, Y, Z, crown); };
    tiers.forEach((r, i) => {
      for (let b = -r; b <= r; b++) for (let a = -r; a <= r; a++) if (Math.abs(a) + Math.abs(b) <= r) leaf(x + a, h + th + i, z + b);
    });
    return { th, crownY: h + th };
  },
})
